% 2026-10-19
% 5 laboratorinis darbas, privaloma uzduotis, 27 variantas
% Jokubas Bridikis

clc; clear;

S.pavardes = {'Bridikis', 'Bridikis', 'Radziunas', 'Purvelis'};
S.amzius = [22 20 21 20];

disp('Pradine struktura:') %[output:595207ef]
disp(S) %[output:985e3cf3]
fieldnames(S) %[output:213cc6c2]

for i = 1:length(S.amzius) %[output:group:69adfdfa]
    fprintf('%-15s %d\n', S.pavardes{i}, S.amzius(i)); %[output:487df4b9]
end %[output:group:69adfdfa]

S = orderfields(S, [2 1]);

disp('Struktura pakeitus lauku tvarka:') %[output:7773bfc8]
disp(S) %[output:046db584]
fieldnames(S) %[output:4f4ae83c]

prev = NaN;
m = input('Iveskite m: ');

while m ~= prev %[output:group:1fbc3145]
    if m < 0
        f = m^2 + 1;
    elseif m == 0
        f = (m + 1)/2;
    else
        f = m^2 - 1;
    end
    disp(['f(' num2str(m) ') = ' num2str(f)]) %[output:01381352]
    prev = m;
    m = input('Iveskite m: ');
end %[output:group:1fbc3145]

disp('Ta pati m reiksme ivesta antra karta. Programa baigta.') %[output:69c68db9]
%%
%Papildoma
clc; clear; close all;

a = [];
b = [];
x = -1;
y = -2;

while x ~= y
    x = round(rand*7);
    y = round(rand*9);
    a(end+1) = x;
    b(end+1) = y;
end

n = length(a);
disp(['Sugeneruota poru: ' num2str(n)]) %[output:80b853a7]
disp(['Sutapes skaicius: ' num2str(x)]) %[output:3dd74650]

figure(1) %[output:6be9d1c8]
plot(1:n, a, 'b-o', 1:n, b, 'r-s', 'LineWidth', 1) %[output:6be9d1c8]
grid on %[output:6be9d1c8]
axis([1 max(n, 2) -0.5 9.5]) %[output:6be9d1c8]
title('Sugeneruotu skaiciu kitimas') %[output:6be9d1c8]
xlabel('Generavimo eiles numeris') %[output:6be9d1c8]
ylabel('Sugeneruotas skaicius') %[output:6be9d1c8]
legend('round(rand*7)', 'round(rand*9)') %[output:6be9d1c8]

